const ingredientAliases={'Пиле':'Пилешко филе','Чушка':'Чушки','Домат':'Домати','Краставица':'Краставици'};
function combineQuantities(a,b){const parse=q=>{const m=String(q).match(/^([\d.]+)\s*(г|мл|бр\.)$/);return m?{n:+m[1],u:m[2]}:null},x=parse(a),y=parse(b);if(x&&y&&x.u===y.u)return `${+(x.n+y.n).toFixed(1)} ${x.u}`;const ax=String(a).match(/^(\d+) бр\. \/ (\d+) г$/),bx=String(b).match(/^(\d+) бр\. \/ (\d+) г$/);if(ax&&bx)return `${+ax[1]+ +bx[1]} бр. / ${+ax[2]+ +bx[2]} г`;if(String(a)===String(b))return a;return `${a} + ${b}`}
function combinedIngredients(m){const out=new Map();[...(m.ingredients||[]),...(m.partnerIngredients||[])].forEach(([raw,q])=>{const name=ingredientAliases[raw]||raw;if(out.has(name))out.set(name,combineQuantities(out.get(name),q));else out.set(name,q)});return [...out.entries()]}
